import{_ as t,o,c as a,a2 as s}from"./chunks/framework.CqdVOxXJ.js";const u=JSON.parse(`{"title":"What's new","description":"","frontmatter":{},"headers":[],"relativePath":"whats-new.md","filePath":"whats-new.md","lastUpdated":1794643263000}`),r={name:"whats-new.md"};function n(i,e,l,h,g,d){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="what-s-new" tabindex="-1">What&#39;s new <a class="header-anchor" href="#what-s-new" aria-label="Permalink to &quot;What&#39;s new&quot;">​</a></h1><p>Changes to Rakkii Ops that this guide covers, newest first. Dates are when the change reached the integration app.</p><h2 id="nov-14-2026-—-guide-v2" tabindex="-1">Nov 14, 2026 — guide v2 <a class="header-anchor" href="#nov-14-2026-—-guide-v2" aria-label="Permalink to &quot;Nov 14, 2026 — guide v2&quot;">​</a></h2><p>The guide is rewritten around <strong>tasks</strong> instead of chapters. Start with your role: <a href="/rakkii-cars-guide/technician/">Technician</a>, <a href="/rakkii-cars-guide/sales/">Sales agent</a> or <a href="/rakkii-cars-guide/desk/">Owner / desk</a>. The old detailed chapters are under <strong>Reference</strong>.</p><h3 id="the-job-page-is-simpler" tabindex="-1">The job page is simpler <a class="header-anchor" href="#the-job-page-is-simpler" aria-label="Permalink to &quot;The job page is simpler&quot;">​</a></h3><ul><li><strong>One next-step button.</strong> The top of every job shows one blue button that names the next thing to do, for example <strong>Save quote →</strong>. It opens the right tab and points at the control. If it&#39;s grey, the reason is written next to it.</li><li><strong>No Quote tab.</strong> The quote is the <strong>Quote</strong> card on the <strong>Work</strong> tab, under the work lines. <strong>Create quote</strong> is now <strong>Save quote</strong>.</li><li><strong>Status buttons sit where the work happens</strong>: <strong>Send to QC</strong> on the bay checklist, <strong>Ready for pickup</strong> on the QC photos card, <strong>Release car</strong> on the Release tab. Less common moves (<strong>Put on hold</strong>, <strong>Cancel job</strong>, <strong>No-show</strong>) are in the header&#39;s <strong>More ▾</strong> menu.</li><li><strong>Overview is a summary.</strong> Edits moved to their tabs. Only the sales advisor and <strong>Change target date or appointment</strong> stay on Overview.</li><li><strong>Work tab</strong>: work lines first, then the <strong>Quote</strong>, <strong>Team</strong> and <strong>Dates</strong> cards side by side, the bay checklist and QC photos.</li><li><strong>Pay tab</strong>: a <strong>Summary</strong> card first, then invoices and payments. Down payment and withholding are folded under <strong>Job money settings</strong>. The PO is on the <strong>Nature and PO</strong> card.</li><li><strong>Files tab</strong>: documents first (intake checklist, pick-up &amp; delivery waiver).</li><li><strong>Release tab</strong>: one <strong>Can the car leave?</strong> list, each line with a button to the fix. The third release check is now <strong>Customer signed acceptance &amp; release</strong>.</li><li><strong>PMS reminder</strong> is chosen when you release the car (<strong>In 3 / 6 / 12 months</strong>); the customer gets one email.</li></ul><h3 id="other-changes" tabindex="-1">Other changes <a class="header-anchor" href="#other-changes" aria-label="Permalink to &quot;Other changes&quot;">​</a></h3><ul><li><strong>Sales</strong> can ask for supplier prices from a job&#39;s <strong>Parts to canvass</strong> card.</li><li><strong>Customers</strong> sign in to the Customer Portal with a 6-digit code sent by email.</li><li>Every date field uses the same date picker (MM/DD/YYYY).</li><li><strong>Finance › Cash</strong> has one <strong>Today</strong> card with money in and out.</li><li><strong>Parts &amp; Inventory</strong> filters by Active, Inactive or All, and shows who moved stock and when.</li></ul><h2 id="oct-31-2026" tabindex="-1">Oct 31, 2026 <a class="header-anchor" href="#oct-31-2026" aria-label="Permalink to &quot;Oct 31, 2026&quot;">​</a></h2><h3 id="released-and-done-are-separate" tabindex="-1">Released and Done are separate <a class="header-anchor" href="#released-and-done-are-separate" aria-label="Permalink to &quot;Released and Done are separate&quot;">​</a></h3><ul><li><strong>Released</strong> means the car is out; <strong>Done</strong> (was &quot;Closed&quot;) means nothing is left on the job. The button is <strong>Mark as done</strong> (<a href="/rakkii-cars-guide/desk/">more</a>).</li><li>Only open checklist items block <strong>Mark as done</strong>. Money still owed (for example an insurer payment) is listed but does not block. The Owner can mark it done anyway with a reason, saved in the Status log.</li><li><strong>Job history</strong> has <strong>Released · not done</strong> and <strong>Done</strong> labels and filters, plus a <strong>Progress</strong> column. On a phone each job is a card.</li></ul><h3 id="see-where-a-job-is-at-a-glance" tabindex="-1">See where a job is at a glance <a class="header-anchor" href="#see-where-a-job-is-at-a-glance" aria-label="Permalink to &quot;See where a job is at a glance&quot;">​</a></h3><ul><li>Every job has a <strong>status banner</strong>, a <strong>steps bar</strong> (&quot;Step 6 of 7 · Paid&quot;, tap it for each step&#39;s date) and ✓ / ● marks on the tabs (<a href="/rakkii-cars-guide/desk/">more</a>).</li><li>Once the car is out, <strong>Not done yet</strong> lists what is still open: checklist items, balances, unpaid suppliers and a payment proof to review.</li><li>On the <strong>Shop board</strong>, each card has a <strong>What&#39;s left</strong> button that opens the same list without leaving the board (<a href="/rakkii-cars-guide/reference/10-workshop-operations-board-calendar-backjobs-contractors">more</a>).</li><li>The balance reads <strong>Quote ₱…</strong> before work, <strong>To collect ₱…</strong> during work and <strong>Customer owes ₱…</strong> once the car is out.</li></ul><h3 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h3><ul><li><strong>Announcements</strong> are at the top, above <strong>Priority jobs</strong>.</li><li>Five figures instead of nineteen: <strong>Cars in shop</strong>, <strong>Ready for pickup</strong>, <strong>On hold</strong>, <strong>Cash in today</strong> and <strong>Overdue invoices</strong>. Empty lists are hidden.</li></ul><h3 id="less-to-think-about-on-the-job-page" tabindex="-1">Less to think about on the job page <a class="header-anchor" href="#less-to-think-about-on-the-job-page" aria-label="Permalink to &quot;Less to think about on the job page&quot;">​</a></h3><ul><li><strong>Print job order</strong> plus a <strong>More papers ▾</strong> menu replace the row of print buttons in the Job order box (<a href="/rakkii-cars-guide/desk/">more</a>).</li><li>On a phone, prints save as a PDF named after the paper and plate, for example <code>Gate pass DEMO 101.pdf</code>. The gate pass shows <strong>Released on</strong>, and the acceptance fills <strong>Work completed</strong> by itself.</li><li><strong>Technicians and dates</strong> shows the dates the app recorded (Car in, Started, Done, Car out, Billed, Paid). The date boxes are behind <strong>Edit dates</strong>.</li><li>The technician list shows technicians first; Owner and Admin are behind <strong>Show owner and admin</strong>.</li><li><strong>Send to QC</strong> asks first if checklist steps are still open.</li><li><strong>QC photos</strong> show one tile per angle with a ✓. Upload buttons show only for missing angles; <strong>Replace a photo</strong> and <strong>Show photos</strong> are a tap away (<a href="/rakkii-cars-guide/technician/">more</a>).</li><li>The Pay tab has a <strong>Down payment</strong> card in plain words, with the overrides behind <strong>Change the down payment</strong>. <strong>Commission and agent fee</strong> moves to the bottom, folded, and the paper previews are behind <strong>Show … preview</strong>.</li><li>The Quote tab with no lines says to add lines first, with a <strong>Go to Work tab</strong> button.</li></ul><h3 id="other-screens" tabindex="-1">Other screens <a class="header-anchor" href="#other-screens" aria-label="Permalink to &quot;Other screens&quot;">​</a></h3><ul><li><strong>Parts &amp; Inventory</strong> fits on an iPad and laptop without scrolling sideways; the unit sits with On hand (&quot;10 pc&quot;) (<a href="/rakkii-cars-guide/reference/09-parts-inventory-canvass-restock-payables">more</a>).</li><li>On an iPad, the top bar no longer overlaps and the Shop board shows two lanes side by side.</li><li>Customer mobiles can be tapped to call; the customer page has <strong>Call</strong> and <strong>Text</strong> links.</li><li><strong>Finance › Payments › Pending proofs</strong> shows the customer&#39;s mobile.</li></ul><h2 id="oct-29-2026" tabindex="-1">Oct 29, 2026 <a class="header-anchor" href="#oct-29-2026" aria-label="Permalink to &quot;Oct 29, 2026&quot;">​</a></h2><h3 id="jobs-tell-you-what-to-do-next" tabindex="-1">Jobs tell you what to do next <a class="header-anchor" href="#jobs-tell-you-what-to-do-next" aria-label="Permalink to &quot;Jobs tell you what to do next&quot;">​</a></h3><ul><li>Every job shows a <strong>next-step banner</strong> under the plate, for example &quot;Add quote lines, start canvass, or start work.&quot; or &quot;Collect PHP 800.00 from customer before release.&quot; (<a href="/rakkii-cars-guide/desk/">more</a>).</li><li>Technicians get their own banner: &quot;Finish the bay checklist (1 step left), then send to QC.&quot; (<a href="/rakkii-cars-guide/technician/">more</a>).</li><li>A waiting customer payment proof shows on the banner and on the <strong>Pay</strong> and <strong>Release</strong> tabs, with a link to <strong>Finance › Payments</strong>.</li></ul><h3 id="qc-photos-lock-ready-for-pickup" tabindex="-1">QC photos lock Ready for pickup <a class="header-anchor" href="#qc-photos-lock-ready-for-pickup" aria-label="Permalink to &quot;QC photos lock Ready for pickup&quot;">​</a></h3><ul><li>While QC photos are missing, <strong>Send to QC</strong> is the main button and <strong>Ready for pickup</strong> is greyed out with the reason (&quot;Need 4 QC photos before Ready/Released (have 0).&quot;).</li></ul><h3 id="quotes-and-margin" tabindex="-1">Quotes and margin <a class="header-anchor" href="#quotes-and-margin" aria-label="Permalink to &quot;Quotes and margin&quot;">​</a></h3><ul><li>If work lines change after a quote, the Quote and Work tabs warn &quot;Work lines changed since the last quote…&quot;.</li><li>Margin is labelled <strong>on cost</strong>: (sell − cost) ÷ cost. The shop&#39;s minimum margin uses the same basis.</li></ul><h3 id="insurance" tabindex="-1">Insurance <a class="header-anchor" href="#insurance" aria-label="Permalink to &quot;Insurance&quot;">​</a></h3><ul><li><strong>Waiting for LOA</strong> now offers <strong>Mark authorized</strong>, <strong>Start work (cash / no LOA)</strong>, <strong>Back to quote</strong>, <strong>Put on hold</strong> and <strong>Cancel job</strong> (<a href="/rakkii-cars-guide/reference/06-lane-2-insurance-claims-and-loa">more</a>).</li><li><strong>Release of Claim</strong>, <strong>Print gate pass</strong> and <strong>Print customer invoice</strong> are on the <strong>Release</strong> tab.</li></ul><h3 id="desk" tabindex="-1">Desk <a class="header-anchor" href="#desk" aria-label="Permalink to &quot;Desk&quot;">​</a></h3><ul><li><strong>New job</strong> asks for the customer, car and work first. Picking a customer on file shows their cars as chips to fill the vehicle.</li><li>&quot;Promised date&quot; is now <strong>Target date</strong>. The <strong>Appointment</strong> (when the car comes in) is a separate date.</li><li><strong>Priority jobs</strong> on the Dashboard, a <strong>search box</strong> in the top bar, and a <strong>Customer activity</strong> feed with a bell count (<a href="/rakkii-cars-guide/reference/10-workshop-operations-board-calendar-backjobs-contractors">more</a>).</li><li>Hard-to-undo actions (create quote, post invoice, record payment, release, approve leave) ask you to confirm.</li></ul><h3 id="hr" tabindex="-1">HR <a class="header-anchor" href="#hr" aria-label="Permalink to &quot;HR&quot;">​</a></h3><ul><li><strong>This week</strong> is Monday to Sunday on Attendance, Payroll and My week.</li><li>Dates read &quot;Oct 29, 2026&quot; everywhere; leave ranges read &quot;Oct 26 – 28, 2026&quot;.</li><li>The <strong>Approve leave</strong> dialog lists the person&#39;s open jobs so you can reassign them.</li><li>The public shop email is <strong><a href="mailto:rakkiicars@gmail.com" target="_blank" rel="noreferrer">rakkiicars@gmail.com</a></strong>.</li></ul>',32)])])}const p=t(r,[["render",n]]);export{u as __pageData,p as default};
